(() => {
  const STORAGE = 'bizsim-demo-v1';
  const $ = (s, root = document) => root.querySelector(s);
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];
  const esc = (v = '') => String(v).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const fmt = (v, digits = 1) => Number(v || 0).toLocaleString('zh-CN', { maximumFractionDigits: digits, minimumFractionDigits: digits });
  const integer = v => Number(v || 0).toLocaleString('zh-CN');
  const pct = v => `${fmt(v, 1)}%`;
  const money = v => `$${fmt(v, 1)}m`;
  const dateTime = v => v ? new Date(v).toLocaleString('zh-CN', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false }) : '未设置';
  const localInputDate = (value, dateOnly = false) => {
    const d = new Date(value);
    if (!Number.isFinite(d.getTime())) return '';
    const pad = n => String(n).padStart(2, '0');
    const date = d.getFullYear() + '-' + pad(d.getMonth()+1) + '-' + pad(d.getDate());
    return dateOnly ? date : date + 'T' + pad(d.getHours()) + ':' + pad(d.getMinutes());
  };
  const uid = p => `${p}_${Math.random().toString(36).slice(2, 8)}`;
  const icons = {
    grid:'▦', book:'▤', cycle:'⟳', users:'♧', send:'↗', chart:'▥', market:'⌁', sliders:'☷', wallet:'▣', settings:'⚙', bolt:'ϟ', car:'▰', plus:'＋', clock:'◷'
  };
  const icon = name => `<span class="ico" aria-hidden="true">${icons[name] || '·'}</span>`;
  const escAttr = esc;
  const STRATEGIES = ['均衡增长', '低价扩张', '技术领先', '高端品牌'];
  const MARKET_MODULES = [
    { key:'demandForecast', label:'需求预测' },
    { key:'costAnalysis', label:'成本分析' },
    { key:'consumerPreferences', label:'消费者偏好' },
    { key:'competitorOverview', label:'竞争团队' },
    { key:'regionalOpportunities', label:'区域机会' },
    { key:'rawMaterials', label:'原材料行情' },
    { key:'sustainability', label:'可持续发展' }
  ];
  const DEFAULT_MARKET_SECTIONS = { demandForecast:true, costAnalysis:true, consumerPreferences:true, competitorOverview:true, regionalOpportunities:true, rawMaterials:true, sustainability:false };
  const normalizedPath = () => window.location.pathname.replace(/\/+$/, '') || '/';
  const portalPath = () => /\/teacher$/.test(normalizedPath()) ? '/teacher' : /\/student$/.test(normalizedPath()) ? '/student' : '/';
  const portalBase = () => { const path=normalizedPath(); const match=path.match(/^(.*)\/(?:teacher|student)$/); return match ? match[1] : path==='/' ? '' : path; };
  const portalUrl = target => `${portalBase()}${target==='/'?'/':target}`;
  const TEAM_NAMES = ['远航汽车', '星河动力', '极光出行', '山海智造', '锋线汽车'];
  const STUDENT_NAMES = ['林沐阳','陈可欣','周子墨','王思远','赵一诺','孙嘉禾','吴雨桐','郑明轩','刘书瑶','黄俊杰','许安然','冯梓涵','何睿哲','高语桐','罗嘉宁','梁宇航','宋知远','谢欣怡','唐景行','韩若溪'];

  function makeSeed() {
    const now = new Date();
    const time = (days, hour = 17) => { const d = new Date(now); d.setDate(d.getDate() + days); d.setHours(hour, 0, 0, 0); return d.toISOString(); };
    const teams = TEAM_NAMES.map((name, i) => ({ id:`team_${i+1}`, name, color:['#2563eb','#8b5cf6','#0891b2','#ea580c','#16a34a'][i], strategy:STRATEGIES[i%4], createdAt:time(-20) }));
    const students = STUDENT_NAMES.map((name, i) => ({ id:`student_${i+1}`, name, email:`student${i+1}@bizsim.edu`, studentNo:`BS${String(2026001+i)}`, teamId:teams[Math.floor(i/4)].id }));
    const courses = [{ id:'course_auto_01', name:'汽车企业经营模拟课程', description:'围绕产品组合、生产运营与市场竞争，体验汽车企业多轮经营决策。', industry:'汽车制造', scenario:'新能源与燃油车双市场', region:'中国 / 欧洲 / 北美', difficulty:'进阶', startDate:time(-12,9), endDate:time(40,18), teamCount:5, membersPerTeam:4, initialCapital:100, initialCapacity:10000, initialMarketShare:20, productCount:3, marketSections:{...DEFAULT_MARKET_SECTIONS}, status:'进行中' }];
    const sim = { id:'sim_auto_01', courseId:courses[0].id, name:'汽车企业经营模拟 · 2026 秋', status:'进行中', currentRound:3, createdAt:time(-12) };
    const rounds = Array.from({length:6},(_,i)=>({ id:`round_${i+1}`, simulationId:sim.id, number:i+1, name:`第 ${i+1} 轮`, status:i<2?'已结束':i===2?'进行中':'未开始', startAt:time(i===2?-1:i*3-8,9), deadline:time(i===2?1:i*3-6,17), allowEdit:i===2, allowEarlySubmit:true, autoAdvance:i<5, publishResults:true, decisionItems:['定价','生产计划','市场营销','研发投入','供应链采购','财务管理'], market:{ round:i+1, demandIndex:[1,1.04,1.08,1.11,1.14,1.18][i], iceGrowth:[1,0,-1,-2,-3,-4][i], evGrowth:[9,10,12,13,14,15][i], materialPriceIndex:[0,1,2,0,-1,1][i], competitorDemand:150000, demand:{ice:52000,ev:46000,hybrid:21000}, regions:{china:.49,europe:.29,northAmerica:.22} } }));
    const data = { schemaVersion:1, users:students, teachers:[{id:'teacher_1',name:'王老师',email:'teacher@bizsim.edu'}], students, courses, simulations:[sim], scenarios:[{id:'scenario_1',simulationId:sim.id,industry:'汽车制造',market:'燃油与新能源',region:'全球',difficulty:'进阶',initialCapital:100,initialCapacity:10000,initialMarketShare:.2,products:['燃油轿车','纯电 SUV','混合动力轿车']}], teams, teamMembers:students.map(s=>({teamId:s.teamId,studentId:s.id,role:'成员'})), rounds, marketConditions:rounds.map(r=>({roundId:r.id,...r.market})), products:[{id:'product_ice',name:'燃油轿车',segment:'燃油车',teamId:null},{id:'product_ev',name:'纯电 SUV',segment:'纯电车',teamId:null},{id:'product_hybrid',name:'混合动力轿车',segment:'混合动力',teamId:null}], decisions:{}, submissions:[], results:[], financialStatements:[], leaderboard:[], events:[] };
    const presets = [
      {strategy:'balanced',prices:{ice:30500,ev:38500,hybrid:34800},marketing:{advertising:5,brand:3,channel:4,promotion:2},research:{battery:4,engine:2,autonomous:2,quality:3,newEnergy:3}},
      {strategy:'value',prices:{ice:27900,ev:35800,hybrid:31900},marketing:{advertising:5,brand:2,channel:4,promotion:4},research:{battery:3,engine:3,autonomous:1,quality:2,newEnergy:2}},
      {strategy:'innovation',prices:{ice:32000,ev:39900,hybrid:35800},marketing:{advertising:4,brand:4,channel:3,promotion:1},research:{battery:6,engine:2,autonomous:4,quality:4,newEnergy:6}},
      {strategy:'premium',prices:{ice:34000,ev:42900,hybrid:37900},marketing:{advertising:4,brand:5,channel:3,promotion:1},research:{battery:4,engine:3,autonomous:3,quality:5,newEnergy:4}},
      {strategy:'balanced',prices:{ice:29800,ev:37900,hybrid:33900},marketing:{advertising:6,brand:3,channel:5,promotion:3},research:{battery:3,engine:4,autonomous:2,quality:3,newEnergy:3}}
    ];
    const base = BizSimEngine.defaults;
    for (let r=0;r<2;r++) {
      const decisions = {};
      teams.forEach((t,i) => {
        const p = presets[i];
        decisions[t.id] = { ...structuredClone(base), ...p, production:{ice:4500+i*200,ev:3500+(4-i)*150,hybrid:1800+i*80}, regions:{china:45+i*2,europe:30-i,northAmerica:25-i}, procurement:{steel:4,battery:4+i%2,chip:3,parts:4}, finance:{loan:i===1?4:0,capex:i===2?2:1,equity:0,dividend:0}, capacityExpansion:300, outsourcing:0, inventoryTarget:8 };
        data.decisions[`${t.id}_${rounds[r].id}`] = decisions[t.id];
      });
      const prior={};
      if (r) data.results.filter(x=>x.round===r).forEach(x=>prior[x.teamId]={cash:x.cash,debt:x.debt,inventory:x.inventory,marketShare:x.marketShare/100,cumulativeScore:x.cumulativeScore});
      const resolved = BizSimEngine.resolveRound(teams,decisions,rounds[r].market,prior,{initialCapital:100,initialCapacity:10000,initialMarketShare:.2});
      data.results.push(...resolved.results);
      rounds[r].status='已结束'; rounds[r].resolvedAt=time(-6+r*3,18);
    }
    const current = rounds[2];
    teams.forEach((t,i)=>{
      const p=presets[i];
      data.decisions[`${t.id}_${current.id}`]={...structuredClone(base),...p,production:{ice:4600+i*150,ev:3600+(4-i)*120,hybrid:1850},regions:{china:47,europe:30,northAmerica:23},procurement:{steel:4,battery:4,chip:3,parts:4},finance:{loan:0,capex:1,equity:0,dividend:0},capacityExpansion:250,outsourcing:0,inventoryTarget:8};
      if(i<3) data.submissions.push({id:`submission_${t.id}_${current.id}`,teamId:t.id,roundId:current.id,decisionId:`${t.id}_${current.id}`,status:'已提交',submittedAt:time(-1,10+i),version:1});
    });
    data.events=[{id:uid('event'),type:'round',message:'第 3 轮已开放决策提交',at:time(-1,9)},{id:uid('event'),type:'result',message:'第 2 轮经营结果已发布',at:time(-4,14)},{id:uid('event'),type:'course',message:'已创建汽车企业经营模拟课程',at:time(-12,9)}];
    return data;
  }

  function loadDb() {
    try { const parsed=JSON.parse(localStorage.getItem(STORAGE)); if(parsed?.schemaVersion===1 && parsed.teams?.length) { parsed.courses.forEach(c=>{c.marketSections={...DEFAULT_MARKET_SECTIONS,...(c.marketSections||{})};}); return parsed; } } catch (_) {}
    const fresh=makeSeed(); localStorage.setItem(STORAGE,JSON.stringify(fresh)); return fresh;
  }
  let db=loadDb();
  const route = portalPath();
  const role = route==='/teacher'?'teacher':route==='/student'?'student':null;
  const savedStudentId = role==='student' ? sessionStorage.getItem('bizsim-student-session') : null;
  const signedStudent = db.students.find(s=>s.id===savedStudentId);
  let ui={role:role||'teacher',page:role==='student'?'student-home':'overview',studentId:signedStudent?.id||null,teamId:signedStudent?.teamId||null,notice:'',modal:'',courseEdit:null,loginError:''};
  const save=()=>localStorage.setItem(STORAGE,JSON.stringify(db));
  const activeSim=()=>db.simulations[0];
  const currentRound=()=>db.rounds.find(r=>r.simulationId===activeSim().id&&r.status==='进行中');
  const subFor=(teamId,roundId)=>db.submissions.find(s=>s.teamId===teamId&&s.roundId===roundId);
  const resultFor=(teamId,roundNumber)=>db.results.find(r=>r.teamId===teamId&&r.round===roundNumber);
  const currentResult=t=>resultFor(t.id,activeSim().currentRound-1)||db.results.filter(r=>r.teamId===t.id).sort((a,b)=>b.round-a.round)[0];
  const teamBy=id=>db.teams.find(t=>t.id===id);
  function toast(msg){ui.notice=msg; render(); setTimeout(()=>{if(ui.notice===msg){ui.notice='';render();}},2600);}
  function emptyState(title,desc){return `<div class="empty-state"><div class="empty-icon">${icon('chart')}</div><strong>${esc(title)}</strong><span>${esc(desc)}</span></div>`;}
  function badge(text,kind='neutral'){return `<span class="badge ${kind}"><i></i>${esc(text)}</span>`;}
  function metric(label,value,sub,iconName,tone='blue',trend=''){return `<article class="metric-card"><div class="metric-top"><span>${esc(label)}</span><span class="metric-icon ${tone}">${icon(iconName)}</span></div><div class="metric-value">${value}</div><div class="metric-foot">${trend?`<b class="${trend.startsWith('-')?'down':'up'}">${esc(trend)}</b>`:''}<span>${sub}</span></div></article>`;}
  function panel(title,subtitle,content,action=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>${content}</section>`;}
  function table(headers,rows,empty='暂无数据'){return rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>${''}`:emptyState(empty,'数据将在模拟进程中显示');}
  function navItems(){return ui.role==='teacher'?[['overview','grid','工作台'],['courses','book','课程管理'],['rounds','cycle','轮次管理'],['teams','users','学生与团队'],['submissions','send','提交监控'],['results','chart','经营分析']]:[['student-home','grid','经营总览'],['market','market','市场分析'],['decisions','sliders','经营决策'],['student-results','chart','财务与排名']];}
  function portalChooser(){return `<main class="portal-screen"><div class="portal-brand"><span class="brand-mark">B</span><div><b>BizSim</b><small>汽车经营模拟教学平台</small></div></div><section class="portal-welcome"><div class="eyebrow">教学模拟平台</div><h1>请选择登录入口</h1><p>教师和学生使用独立入口与演示会话。</p><div class="portal-cards"><a class="portal-card" href="${portalUrl('/teacher')}"><span class="portal-card-icon">教师</span><b>教师端</b><small>课程、轮次、团队和经营结果管理</small><strong>进入教师端 →</strong></a><a class="portal-card" href="${portalUrl('/student')}"><span class="portal-card-icon student">学生</span><b>学生端</b><small>查看所属企业并提交本轮经营决策</small><strong>进入学生端 →</strong></a></div><div class="demo-credentials">演示账号：教师 teacher@bizsim.edu / teacher123；学生选择名册账号 / student123</div></section></main>`;}
  function loginPage(){const teacher=ui.role==='teacher';const studentOptions=db.students.map(st=>`<option value="${escAttr(st.email)}" ${st.id===db.students[0]?.id?'selected':''}>${esc(st.name)} · ${esc(st.studentNo)} · ${esc(teamBy(st.teamId)?.name||'未分组')}</option>`).join('');return `<main class="login-screen"><a class="back-home" href="${portalUrl('/' )}">← 返回入口选择</a><section class="login-card"><div class="login-brand"><span class="brand-mark">B</span><div><b>BizSim</b><small>汽车经营模拟教学平台</small></div></div><div class="eyebrow">${teacher?'教师工作空间':'学生工作空间'}</div><h1>${teacher?'教师登录':'学生登录'}</h1><p class="login-intro">${teacher?'登录后管理课程、模拟轮次和团队结果。':'登录后进入你所属团队，查看市场并提交经营决策。'}</p><form id="loginForm" data-role="${ui.role}">${teacher?`<label class="form-field"><span>教师邮箱</span><input name="email" type="email" value="teacher@bizsim.edu" autocomplete="username" required></label>`:`<label class="form-field"><span>学生账号</span><select name="email" autocomplete="username">${studentOptions}</select></label>`}<label class="form-field"><span>演示密码</span><input name="password" type="password" placeholder="${teacher?'teacher123':'student123'}" autocomplete="current-password" required></label>${ui.loginError?`<div class="login-error">${esc(ui.loginError)}</div>`:''}<button class="btn primary full" type="submit">登录${teacher?'教师端':'学生端'}</button></form><div class="login-hint">${teacher?'教师演示账号：teacher@bizsim.edu':'学生演示密码：student123'}<br>这是本地 Demo 登录，用于区分演示身份。</div></section></main>`;}
  function shell(content){
    const teacher=ui.role==='teacher';
    const round=currentRound();
    const person=teacher?db.teachers[0]:db.students.find(s=>s.id===ui.studentId);
    return `<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">B</div><div><b>BizSim</b><small>汽车经营模拟平台</small></div></div><div class="workspace-label">${teacher?'教师工作空间':'学生工作空间'}</div><nav class="side-nav">${navItems().map(([id,ic,label])=>`<button class="nav-item ${ui.page===id?'active':''}" data-page="${id}">${icon(ic)}<span>${label}</span>${id==='submissions'&&teacher?`<em>${db.teams.length-db.submissions.filter(s=>s.roundId===round?.id&&s.status==='已提交').length}</em>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="course-mini"><span class="live-dot"></span><div><b>${esc(activeSim().name)}</b><small>${round?.name||'当前没有进行中的轮次'}</small></div></div>${teacher?`<button class="sidebar-help" data-action="reset">${icon('settings')}<span>重置演示数据</span></button>`:''}</div></aside><main class="main-area"><header class="topbar"><div class="crumb"><span>BizSim</span><b>/</b><strong>${navItems().find(n=>n[0]===ui.page)?.[2]||'工作台'}</strong></div><div class="top-actions"><div class="round-chip">${icon('clock')}<span>${round?.name||'等待教师开放轮次'}</span>${round?'<i></i>':''}</div><div class="session-identity"><span class="session-name">${esc(person?.name||'演示账号')}</span><small>${teacher?'教师端':'学生端 · '+esc(teamBy(ui.teamId)?.name||'未分组')}</small></div><button class="btn secondary small" data-action="logout">退出登录</button></div></header><div class="page-content">${content}</div><footer class="footer"><span>BizSim 教学模拟平台</span><span>${teacher?'教师端独立会话':'学生端独立会话'} · 本地演示数据</span></footer></main>${ui.notice?`<div class="toast">✓ &nbsp;${esc(ui.notice)}</div>`:''}${ui.modal?modalHtml():''}</div>`;
  }

    function overviewPage(){
    const round=currentRound(); const submitted=db.submissions.filter(s=>s.roundId===round?.id&&s.status==='已提交').length; const finished=db.rounds.filter(r=>r.status==='已结束').length;
    const course=db.courses[0];
    const activity=db.events.slice().sort((a,b)=>new Date(b.at)-new Date(a.at)).slice(0,5);
    const activityRows=activity.map((e,i)=>`<div class="activity-row"><span class="activity-dot ${i===0?'primary':''}"></span><div><b>${esc(e.message)}</b><small>${dateTime(e.at)}</small></div></div>`);
    const teamResultRows=db.teams.map(t=>{const r=currentResult(t)||{};return `<tr><td><div class="team-name"><span class="team-avatar" style="--team:${t.color}">${esc(t.name.slice(0,1))}</span><div><b>${esc(t.name)}</b><small>${esc(t.strategy)}</small></div></div></td><td>${money(r.revenue)}</td><td class="${r.netProfit>=0?'positive':'negative'}">${money(r.netProfit)}</td><td>${pct(r.marketShare)}</td><td>${r.score?fmt(r.score,0):'—'}</td></tr>`;});
    return `<div class="page-heading"><div><div class="eyebrow">教师端 · ${esc(course.industry)}</div><h1>教师工作台</h1><p>欢迎回来，${esc(db.teachers[0].name)}。查看课程进度与团队经营表现。</p></div><button class="btn primary" data-action="new-course">${icon('plus')}创建课程</button></div><div class="metrics-grid">${metric('课程数量',db.courses.length,'个教学课程','book','blue')}${metric('学生数量',db.students.length,'位已加入学生','users','violet')}${metric('团队数量',db.teams.length,'支模拟企业','car','cyan')}${metric('当前模拟轮次',`${round?.number||0} / ${db.rounds.length}`,'第 '+finished+' 轮已完成','cycle','orange')}${metric('本轮提交率',pct(db.teams.length?submitted/db.teams.length*100:0),`${submitted} / ${db.teams.length} 支团队已提交`,'send','green')}</div><div class="dashboard-grid"><div class="main-column">${panel('课程进度','当前课程的模拟状态与关键参数',`<div class="course-summary"><div class="course-banner"><div class="banner-icon">${icon('car')}</div><div><span class="banner-overline">${esc(course.industry)} · ${esc(course.difficulty)}</span><h3>${esc(course.name)}</h3><p>${esc(course.description)}</p></div><div class="course-status">${badge('进行中','success')}<small>创建于 ${dateTime(course.startDate)}</small></div></div><div class="course-facts"><div><small>模拟场景</small><b>${esc(course.scenario)}</b></div><div><small>市场区域</small><b>${esc(course.region)}</b></div><div><small>初始资金</small><b>${money(course.initialCapital)}</b></div><div><small>团队规模</small><b>${db.teams.length} 支团队 · ${db.students.length} 位学生</b></div></div><div class="progress-block"><div class="progress-label"><span>模拟整体进度</span><b>${Math.round(finished/db.rounds.length*100)}%</b></div><div class="progress-track"><i style="width:${finished/db.rounds.length*100}%"></i></div><div class="progress-meta"><span>第 ${round?.number||db.rounds.length} / ${db.rounds.length} 轮</span><span>截止 ${dateTime(round?.deadline)}</span></div></div></div>`,`<button class="btn light small" data-page="courses">查看课程</button>`)}${panel('团队经营表现','基于最近一轮已发布的模拟结果',table(['团队','营业收入','净利润','市场份额','综合得分'],teamResultRows),`<button class="text-button" data-page="results">查看分析 ${icon('chart')}</button>`)}</div><div class="side-column">${panel('本轮决策提交','第 '+(round?.number||'—')+' 轮团队完成情况',`<div class="submission-summary"><div class="donut" style="--progress:${db.teams.length?submitted/db.teams.length*100:0}%"><div><b>${submitted}/${db.teams.length}</b><small>已提交</small></div></div><div class="summary-legend"><span><i class="legend-green"></i>已提交 <b>${submitted}</b></span><span><i class="legend-gray"></i>待提交 <b>${db.teams.length-submitted}</b></span><small>截止时间 ${dateTime(round?.deadline)}</small></div></div><button class="btn secondary full" data-page="submissions">查看提交状态</button>`)}${panel('最近活动','课程中最新发生的事件',`<div class="activity-list">${activityRows.join('')}</div>`)}</div></div>`;
  }

  function coursesPage(){
    const rows=db.courses.map(c=>`<tr><td><div class="course-table-name"><span class="course-table-icon">${icon('car')}</span><div><b>${esc(c.name)}</b><small>${esc(c.industry)} · ${esc(c.difficulty)}</small></div></div></td><td>${esc(c.scenario)}</td><td>${esc(c.region)}</td><td>${c.teamCount} 支 / ${c.membersPerTeam} 人</td><td>${badge(c.status,c.status==='进行中'?'success':'neutral')}</td><td>${dateTime(c.endDate)}</td><td><div class="table-actions"><button data-action="edit-course" data-id="${c.id}" title="编辑">编辑</button><button data-action="copy-course" data-id="${c.id}" title="复制">复制</button><button data-action="delete-course" data-id="${c.id}" title="删除">删除</button></div></td></tr>`);
    return `<div class="page-heading"><div><div class="eyebrow">课程教学管理</div><h1>课程管理</h1><p>创建汽车行业模拟课程，配置场景、市场和团队规模。</p></div><button class="btn primary" data-action="new-course">${icon('plus')}创建课程</button></div><div class="metrics-grid compact">${metric('全部课程',db.courses.length,'个课程','book','blue')}${metric('进行中',db.courses.filter(c=>c.status==='进行中').length,'个模拟课程','cycle','green')}${metric('课程学生',db.students.length,'位学生','users','violet')}${metric('已配置轮次',db.rounds.length,'个模拟轮次','clock','orange')}</div>${panel('课程列表','课程设置可在模拟开始后继续调整',table(['课程名称','模拟场景','市场区域','团队配置','状态','结束时间','操作'],rows,'还没有课程'),`<span class="panel-counter">${db.courses.length} 个课程</span>`)}`;
  }

  function roundsPage(){
    const rows=db.rounds.slice().sort((a,b)=>a.number-b.number).map(r=>{const count=db.submissions.filter(s=>s.roundId===r.id&&s.status==='已提交').length; const active=r.number===activeSim().currentRound; return `<tr><td><span class="round-number">${String(r.number).padStart(2,'0')}</span></td><td><b>${esc(r.name)}</b><small class="cell-sub">${r.decisionItems.join(' · ')}</small></td><td>${dateTime(r.startAt)}</td><td>${dateTime(r.deadline)}</td><td>${r.status==='进行中'?`${count}/${db.teams.length} 已提交`:'—'}</td><td>${badge(r.status,r.status==='进行中'?'success':r.status==='已结束'?'neutral':'warning')}</td><td><div class="table-actions">${r.status==='未开始'?`<button data-action="edit-round" data-id="${r.id}">设置</button><button data-action="start-round" data-id="${r.id}">开始</button><button data-action="delete-round" data-id="${r.id}">删除</button>`:r.status==='进行中'?`<button data-action="edit-round" data-id="${r.id}">设置</button><button data-action="finish-round" data-id="${r.id}">结束并计算</button>`:`<button data-action="view-round" data-id="${r.id}">查看结果</button>`}</div></td></tr>`;});
    return `<div class="page-heading"><div><div class="eyebrow">模拟轮次控制</div><h1>轮次管理</h1><p>自定义模拟节奏、决策项目与市场参数，管理每一轮的开启和结算。</p></div><div class="heading-actions"><button class="btn secondary" data-action="reset-simulation">${icon('cycle')}重置模拟</button><button class="btn primary" data-action="new-round">${icon('plus')}添加轮次</button></div></div><div class="notice-bar"><span class="notice-symbol">i</span><div><b>当前模拟进度：第 ${activeSim().currentRound} 轮 / 共 ${db.rounds.length} 轮</b><small>结束当前轮次将锁定已提交决策、计算市场结果，并开放下一轮。</small></div><span class="notice-deadline">截止 ${dateTime(currentRound()?.deadline)}</span></div>${panel('模拟轮次','轮次总数可随时扩展；未开始的轮次可以调整或删除',table(['轮次','决策项目','开始时间','截止时间','提交情况','状态','操作'],rows),`<span class="panel-counter">${db.rounds.length} 轮</span>`)}`;
  }

  function teamsPage(){
    const rows=db.teams.map(t=>{const members=db.students.filter(s=>s.teamId===t.id);const r=currentResult(t)||{};return `<tr><td><div class="team-name"><span class="team-avatar" style="--team:${t.color}">${esc(t.name.slice(0,1))}</span><div><b>${esc(t.name)}</b><small>${esc(t.strategy)}</small></div></div></td><td>${members.length} 人 <small class="cell-sub">${members.map(s=>esc(s.name)).join('、')}</small></td><td>${money(r.cash??100)}</td><td>${money(r.revenue)}</td><td>${pct(r.marketShare)}</td><td>${r.score?fmt(r.score,0):'—'}</td><td><button class="text-button" data-action="team-detail" data-id="${t.id}">查看经营</button></td></tr>`;});
    const studentRows=db.students.map(s=>`<tr><td><b>${esc(s.name)}</b></td><td>${esc(s.studentNo)}</td><td>${esc(s.email)}</td><td>${esc(teamBy(s.teamId)?.name||'未分组')}</td><td><button class="text-button" data-action="edit-student" data-id="${s.id}">编辑分组</button></td></tr>`);
    return `<div class="page-heading"><div><div class="eyebrow">学生与团队管理</div><h1>学生与团队</h1><p>管理学生名册、团队分配和模拟企业经营状态。</p></div><div class="heading-actions"><button class="btn secondary" data-action="new-team">${icon('plus')}创建团队</button><button class="btn primary" data-action="new-student">${icon('plus')}添加学生</button></div></div><div class="metrics-grid compact">${metric('模拟团队',db.teams.length,'支企业','car','blue')}${metric('已分配学生',db.students.filter(s=>s.teamId).length,'位学生','users','green')}${metric('平均每队',fmt(db.students.length/Math.max(1,db.teams.length),1),'位学生','grid','violet')}${metric('当前轮次',`第 ${activeSim().currentRound} 轮`,'决策进行中','cycle','orange')}</div><div class="team-results-card">${panel('团队经营概况','最近已结算轮次的财务与市场表现',table(['模拟企业','团队成员','现金余额','营业收入','市场份额','综合得分','详情'],rows))}</div>${panel('学生名册','学生通过独立学生入口登录，账号关联所属团队',table(['学生姓名','学号','邮箱','所属团队','操作'],studentRows))}`;
  }

  function submissionsPage(){
    const r=currentRound();
    const rows=db.teams.map(t=>{const s=subFor(t.id,r?.id);const canEdit=r?.allowEdit;return `<tr><td><div class="team-name"><span class="team-avatar" style="--team:${t.color}">${esc(t.name.slice(0,1))}</span><div><b>${esc(t.name)}</b><small>${esc(t.strategy)}</small></div></div></td><td>${s?badge('已提交','success'):badge('待提交','warning')}</td><td>${s?dateTime(s.submittedAt):'—'}</td><td>${s?`v${s.version}`:'—'}</td><td>${canEdit?'允许修改':'提交后锁定'}</td><td>${s?`<button class="text-button" data-action="view-submission" data-id="${t.id}">查看决策</button>`:'等待团队提交'}</td></tr>`;});
    const n=db.submissions.filter(s=>s.roundId===r?.id&&s.status==='已提交').length;
    return `<div class="page-heading"><div><div class="eyebrow">决策提交监控</div><h1>提交监控</h1><p>追踪团队决策提交状态、提交时间和修改权限。</p></div><button class="btn secondary" data-action="export-submissions">导出提交记录</button></div><div class="submission-callout"><div class="callout-main"><span class="callout-icon">${icon('send')}</span><div><small>第 ${r?.number||'—'} 轮提交进度</small><b>${n} / ${db.teams.length} 支团队已提交</b></div></div><div class="wide-progress"><div class="progress-track"><i style="width:${n/db.teams.length*100}%"></i></div><small>${pct(n/db.teams.length*100)} 完成</small></div><div class="callout-deadline"><small>本轮截止时间</small><b>${dateTime(r?.deadline)}</b></div></div>${panel('团队提交状态','教师可在本轮结束前查看已提交决策',table(['团队','提交状态','提交时间','版本','修改权限','决策详情'],rows),`<span class="panel-counter">${n} 已提交 · ${db.teams.length-n} 待提交</span>`)}`;
  }

  function selectedResultsRound(){
    const nums = [...new Set(db.results.map(r=>r.round))].sort((a,b)=>a-b);
    return nums.includes(ui.resultsRound) ? ui.resultsRound : nums.at(-1) || 0;
  }
  function resultsPage(){
    const roundNums=[...new Set(db.results.map(r=>r.round))].sort((a,b)=>a-b);
    const latest=roundNums[roundNums.length-1]||0;
    const chosen=selectedResultsRound();
    const rows=db.teams.map(t=>{const r=resultFor(t.id,chosen)||{};return `<tr><td><span class="rank rank-${r.rank||5}">${r.rank||'—'}</span></td><td><div class="team-name"><span class="team-avatar" style="--team:${t.color}">${esc(t.name.slice(0,1))}</span><div><b>${esc(t.name)}</b><small>${esc(t.strategy)}</small></div></div></td><td>${money(r.revenue)}</td><td class="${r.netProfit>=0?'positive':'negative'}">${money(r.netProfit)}</td><td>${pct(r.marketShare)}</td><td>${integer(r.totalSales)}</td><td>${money(r.productionCost)}</td><td>${integer(r.inventoryUnits)}</td><td>${money(r.cash)}</td><td><b>${fmt(r.score,0)}</b></td></tr>`;});
    const leader=db.teams.map(t=>resultFor(t.id,chosen)).filter(Boolean).sort((a,b)=>b.score-a.score)[0];
    const totals=db.teams.map(t=>resultFor(t.id,chosen)).filter(Boolean);
    const avgProfit=totals.length?totals.reduce((a,r)=>a+r.netProfit,0)/totals.length:0;
    return `<div class="page-heading"><div><div class="eyebrow">经营结果分析</div><h1>经营结果分析</h1><p>横向比较团队财务表现、市场份额和经营效率。</p></div><label class="select-filter"><span>结果轮次</span><select id="resultsRound">${roundNums.map(n=>`<option value="${n}" ${n===chosen?'selected':''}>第 ${n} 轮</option>`).join('')}</select></label></div><div class="metrics-grid compact">${metric('领先团队',leader?.teamName||'暂无','综合得分排名第一','chart','blue')}${metric('本轮平均净利润',money(avgProfit),'团队平均水平','wallet',avgProfit>=0?'green':'orange')}${metric('本轮总销量',integer(totals.reduce((a,r)=>a+r.totalSales,0)),'辆','car','cyan')}${metric('已结算轮次',roundNums.length,'轮历史结果','cycle','violet')}</div><div class="chart-grid"><section class="panel"><div class="panel-head"><div><h2>收入与净利润</h2><p>各团队本轮财务表现 · 百万美元</p></div><span class="chart-key"><i class="key-revenue"></i>收入 <i class="key-profit"></i>净利润</span></div>${barChart(totals,'revenue','netProfit')}</section><section class="panel"><div class="panel-head"><div><h2>得分排行榜</h2><p>综合经营得分（0–100）</p></div></div>${scoreChart(totals)}</section></div>${panel('团队横向对比',`第 ${chosen||'—'} 轮 · 经营结果及财务指标`,table(['排名','团队','营业收入','净利润','市场份额','销售数量','生产成本','期末库存','现金余额','综合得分'],rows),`<button class="text-button" data-action="export-results">导出报表</button>`)}`;
  }

  function barChart(rows,a,b){if(!rows.length)return emptyState('暂无结果','结束当前轮次后将生成团队经营数据');const max=Math.max(...rows.map(r=>r[a]||0),1);return `<div class="bar-chart">${rows.map(r=>`<div class="bar-group"><div class="bar-pair"><div class="vbar revenue" style="height:${Math.max(3,(r[a]||0)/max*100)}%" title="收入 ${money(r[a])}"></div><div class="vbar profit ${r[b]<0?'loss':''}" style="height:${Math.max(3,Math.abs(r[b]||0)/max*100)}%" title="净利润 ${money(r[b])}"></div></div><b>${esc(r.teamName)}</b><small>${money(r[a])}</small></div>`).join('')}</div>`;}
  function scoreChart(rows){if(!rows.length)return emptyState('暂无结果','等待模拟计算');return `<div class="score-list">${rows.slice().sort((a,b)=>a.rank-b.rank).map(r=>`<div class="score-row"><span class="score-rank">${r.rank}</span><b>${esc(r.teamName)}</b><div class="score-track"><i style="width:${r.score}%"></i></div><strong>${fmt(r.score,0)}</strong></div>`).join('')}</div>`;}

  function studentHome(){
    const team=teamBy(ui.teamId)||db.teams[0];const round=currentRound();const result=currentResult(team)||{};const submission=subFor(team.id,round?.id);const history=db.results.filter(r=>r.teamId===team.id).sort((a,b)=>b.round-a.round);
    const prev=resultFor(team.id,activeSim().currentRound-1)||result;
    const rows=history.slice(0,3).map(r=>`<tr><td>第 ${r.round} 轮</td><td>${money(r.revenue)}</td><td class="${r.netProfit>=0?'positive':'negative'}">${money(r.netProfit)}</td><td>${pct(r.marketShare)}</td><td>${fmt(r.score,0)}</td><td>${badge('已发布','success')}</td></tr>`);
    const state=submission?badge('已提交','success'):badge('草稿未提交','warning');
    return `<div class="page-heading student-heading"><div><div class="eyebrow">学生端 · ${esc(team.name)}</div><h1>经营总览</h1><p>你好，${esc(db.students.find(s=>s.id===ui.studentId)?.name||'同学')}。这是你的企业最新经营情况。</p></div><div class="student-deadline"><small>第 ${round?.number||'—'} 轮 · 决策截止</small><b>${dateTime(round?.deadline)}</b>${state}</div></div><div class="round-progress-card"><div class="round-step"><div class="round-step-icon">${icon('cycle')}</div><div><small>当前模拟轮次</small><b>第 ${round?.number||'—'} 轮 <span>/ 共 ${db.rounds.length} 轮</span></b></div></div><div class="round-progress"><div class="round-progress-label"><span>模拟进度</span><b>${Math.round((activeSim().currentRound-1)/db.rounds.length*100)}%</b></div><div class="progress-track"><i style="width:${(activeSim().currentRound-1)/db.rounds.length*100}%"></i></div></div><button class="btn primary" data-page="decisions">${submission?'查看本轮决策':'开始本轮决策'}　→</button></div><div class="metrics-grid">${metric('营业收入',money(prev.revenue),'最近一轮已结算','wallet','blue')}${metric('净利润',money(prev.netProfit),prev.netProfit>=0?'经营盈利':'需要优化成本','chart',prev.netProfit>=0?'green':'orange')}${metric('现金余额',money(prev.cash??100),'可用企业资金','wallet','violet')}${metric('市场份额',pct(prev.marketShare),'汽车市场占有率','market','cyan')}${metric('销量与库存',integer(prev.totalSales),'库存 '+integer(prev.inventoryUnits)+' 辆','car','orange')}${metric('产能利用率',pct(prev.capacityUtilization),'客户满意度 '+fmt(prev.customerSatisfaction,0),'grid','green')}</div><div class="dashboard-grid"><div class="main-column">${panel('企业经营趋势',`${team.name} · 已结算轮次`,studentTrend(team))}${panel('最近模拟结果','最近三轮的经营成果',table(['模拟轮次','营业收入','净利润','市场份额','综合得分','结果状态'],rows))}</div><div class="side-column">${panel('本轮决策状态','提交后等待教师结算',`<div class="student-status-card">${state}<h3>${submission?'决策已送达':'还有决策尚未提交'}</h3><p>${submission?`提交时间：${dateTime(submission.submittedAt)}。${round?.allowEdit?'教师结算前仍可修改。':'本轮已锁定。'}`:'请完成经营决策并在截止时间前提交。'}</p><button class="btn ${submission?'secondary':'primary'} full" data-page="decisions">${submission?'管理本轮决策':'填写经营决策'}</button></div>`)}${panel('企业综合得分','第 '+(history[0]?.round||'—')+' 轮排行榜',`<div class="rank-highlight"><span class="rank rank-${prev.rank||5}">${prev.rank||'—'}</span><div><b>${prev.rank?`第 ${prev.rank} 名`:'待计算'}</b><small>综合得分 ${fmt(prev.score,0)} / 100</small></div></div><div class="mini-rank">${db.teams.map(t=>{const r=currentResult(t)||{};return `<div><span>${esc(t.name)}</span><b>${r.score?fmt(r.score,0):'—'}</b></div>`}).sort((a,b)=>Number(b.match(/<b>(.*?)<\/b>/)?.[1]||0)-Number(a.match(/<b>(.*?)<\/b>/)?.[1]||0)).join('')}</div>`)}</div></div>`;
  }
  function studentTrend(team){const arr=db.results.filter(r=>r.teamId===team.id).sort((a,b)=>a.round-b.round);if(!arr.length)return emptyState('暂无趋势数据','完成第一轮模拟后展示经营趋势');const max=Math.max(...arr.map(r=>r.revenue),1);return `<div class="trend-chart">${arr.map(r=>`<div class="trend-col"><div class="trend-value">${money(r.revenue)}</div><div class="trend-bar" style="height:${Math.max(8,r.revenue/max*100)}%"></div><small>第 ${r.round} 轮</small></div>`).join('')}</div>`;}

  function marketPage(){
    const round=currentRound();
    const m=round?.market||db.rounds.at(-1).market;
    const team=teamBy(ui.teamId);
    const course=db.courses.find(c=>c.id===activeSim().courseId)||db.courses[0];
    const enabled={...DEFAULT_MARKET_SECTIONS,...(course.marketSections||{})};
    const results=db.teams.map(t=>({team:t,result:currentResult(t)||{}})).sort((a,b)=>(b.result.marketShare||0)-(a.result.marketShare||0));
    const own=results.find(x=>x.team.id===team?.id);
    const opportunity={china:m.regions.china,europe:m.regions.europe,northAmerica:m.regions.northAmerica};
    const demandValue=(key,growth)=>Math.round((m.demand?.[key]||0)*(m.demandIndex||1)*(1+growth/100));
    const reports=[];
    if(enabled.demandForecast) reports.push(panel('需求预测','本轮市场需求与增长判断',`<div class="market-narrative"><p>本轮综合需求指数为 <b>${fmt((m.demandIndex||1)*100,0)}</b>，基准值为 100。燃油车市场增长率为 <b>${fmt(m.iceGrowth,1)}%</b>，纯电市场增长率为 <b>${fmt(m.evGrowth,1)}%</b>。</p><ul class="report-points"><li><b>燃油车：</b>基础市场 ${integer(m.demand.ice)} 辆，结合需求指数与增长率后，预计约 ${integer(demandValue('ice',m.iceGrowth))} 辆。</li><li><b>纯电车：</b>基础市场 ${integer(m.demand.ev)} 辆，预计约 ${integer(demandValue('ev',m.evGrowth))} 辆。</li><li><b>混合动力：</b>基础市场 ${integer(m.demand.hybrid)} 辆，预计约 ${integer(demandValue('hybrid',(m.iceGrowth+m.evGrowth)/2))} 辆。</li></ul><p class="report-note">这是行业需求预测。企业最终可实现销量还会受到售价、产品竞争力、区域投入、产能和库存影响。</p></div>`));
    if(enabled.costAnalysis) reports.push(panel('成本分析','成本变化如何影响企业利润',`<div class="market-narrative"><p>当前原材料价格指数为 <b>${fmt(100+(m.materialPriceIndex||0),0)}</b>（上一期为 100），${m.materialPriceIndex>0?'原材料成本环境较上一期偏高。':m.materialPriceIndex<0?'原材料成本环境较上一期有所缓和。':'原材料成本环境与上一期接近。'}</p><p>成本主要由车型生产成本、营销预算、研发投入、运营费用、产能扩建、资本支出和贷款利息组成。提高钢材、电池、芯片或零部件采购等级会改变对应车型的材料成本系数。</p><p class="report-note">${own?.result?.productionCost!==undefined?`你的企业最近已结算一轮生产成本为 ${money(own.result.productionCost)}。`: '企业成本报表将在首轮结算后显示。'} 优化产量与采购配置有助于控制现金支出。</p></div>`));
    if(enabled.consumerPreferences) reports.push(panel('消费者偏好','模拟市场调研摘要',`<div class="market-narrative"><p>本轮消费者调研显示，购车决策主要受到价格、续航与能耗、品牌、安全品质和智能配置影响。</p><ul class="report-points"><li>价格与总用车成本仍是最主要的筛选因素。</li><li>新能源细分市场更加关注续航、补能体验和电池安全。</li><li>品牌口碑与产品品质会影响消费者对售价的接受度。</li><li>智能配置会提升部分细分人群的购买意愿。</li></ul><p class="report-note">学生提交的营销和研发投入会影响模拟中的产品竞争力；以上为教学用调研摘要。</p></div>`));
    if(enabled.competitorOverview) reports.push(panel('竞争团队','最近一轮结果中的相对位置',`<div class="market-narrative"><p>${own?.result?.rank?`你的团队“${esc(team.name)}”最近已发布结果排名第 ${own.result.rank}，市场份额为 ${pct(own.result.marketShare)}，综合得分 ${fmt(own.result.score,0)}。`:'本团队尚无已发布的经营结果。'}</p><ul class="report-points">${results.slice(0,3).map(({team:t,result:r})=>`<li><b>${esc(t.name)}</b>：${esc(t.strategy)}策略，市场份额 ${pct(r.marketShare)}，综合得分 ${fmt(r.score,0)}。</li>`).join('')}</ul><p class="report-note">市场份额依据各团队决策估算；实际销量还受各团队自己的需求预测和产能限制。</p></div>`));
    if(enabled.regionalOpportunities) reports.push(panel('区域机会','不同区域的市场机会与投入方向',`<div class="market-narrative"><p>本轮区域市场容量分布为：中国 ${pct(opportunity.china*100)}、欧洲 ${pct(opportunity.europe*100)}、北美 ${pct(opportunity.northAmerica*100)}。</p><ul class="report-points"><li><b>中国：</b>关注新能源产品渗透与本地渠道覆盖。</li><li><b>欧洲：</b>关注能耗、排放要求和品牌认可。</li><li><b>北美：</b>关注车型偏好、销售覆盖与售后服务能力。</li></ul><p class="report-note">区域投入比例会进入需求估算；学生应在决策表中将区域投入占比合计设为 100%。</p></div>`));
    if(enabled.rawMaterials) reports.push(panel('原材料行情','主要零部件采购环境',`<div class="market-narrative"><p>原材料综合价格指数 ${fmt(100+(m.materialPriceIndex||0),0)}。模拟行情中，动力电池指数约为 ${fmt(105+(m.materialPriceIndex||0),0)}，汽车芯片指数约为 ${fmt(108+(m.materialPriceIndex||0),0)}。</p><p>钢材主要影响燃油与混合动力车型材料成本；动力电池和芯片主要影响纯电车型材料成本；零部件采购影响各车型的基础材料成本。</p><p class="report-note">采购等级在当前 Demo 中影响成本系数，尚未模拟供应商交付风险或采购质量带来的性能变化。</p></div>`));
    if(enabled.sustainability){const env=m.sustainability||{carbonPrice:48,emissionReductionTarget:12,batteryRecyclingRate:72,evMarketShare:39};reports.push(panel('可持续发展','本轮环境与产业转型观察',`<div class="market-narrative"><p>本轮模拟碳成本参考值为每吨 ${fmt(env.carbonPrice,0)} 美元，行业减排目标为 ${fmt(env.emissionReductionTarget,0)}%，动力电池回收率参考值为 ${fmt(env.batteryRecyclingRate,0)}%。</p><p>纯电汽车市场占比参考值约 ${fmt(env.evMarketShare,0)}%。电池技术、新能源技术和产品质量投入可能提升企业在新能源市场中的竞争力。</p><p class="report-note">这些可持续发展指标目前用于课程阅读与情境讨论，尚未直接计入企业利润或综合得分。</p></div>`));}
    return `<div class="page-heading"><div><div class="eyebrow">市场信息分析 · ${esc(course.name)}</div><h1>市场分析</h1><p>课程教师选择的市场简报模块以文字形式呈现，供团队在提交决策前阅读。</p></div><div class="market-period">${icon('clock')}第 ${round?.number||'—'} 轮 · ${esc(team?.name||'')}</div></div><section class="market-brief-intro"><span class="brief-mark">i</span><div><b>本轮市场简报</b><p>需求指数 ${fmt((m.demandIndex||1)*100,0)}；纯电市场增长 ${fmt(m.evGrowth,1)}%；原材料指数 ${fmt(100+(m.materialPriceIndex||0),0)}。市场参数由教师配置，企业决策会在轮次结算时进入经营计算。</p></div></section><div class="market-report-grid">${reports.length?reports.join(''):emptyState('教师尚未开放市场简报模块','请联系教师调整课程的市场分析内容')}</div>`;
  }

  const field=(label,path,value,min,max,step='1',suffix='',hint='')=>`<label class="form-field"><span>${label}${suffix?` <small>(${suffix})</small>`:''}</span><div class="input-suffix"><input type="number" name="${path}" value="${value}" min="${min}" max="${max}" step="${step}" required><i>${suffix==='万美元'?'m':suffix==='元/辆'?'元':''}</i></div>${hint?`<small class="field-hint">${hint}</small>`:''}</label>`;
  function decisionsPage(){
    const team=teamBy(ui.teamId)||db.teams[0],round=currentRound();if(!round)return `<div class="page-heading"><div><h1>经营决策</h1><p>模拟已完成。</p></div></div>${emptyState('模拟已完成','教师可以重置模拟开启新一轮')}</div>`;
    const key=`${team.id}_${round.id}`;const d=BizSimEngine.mergeDecision(db.decisions[key]||{});const sub=subFor(team.id,round.id);const locked=!!sub&&!round.allowEdit;
    return `<div class="page-heading"><div><div class="eyebrow">决策工作台 · 第 ${round.number} 轮</div><h1>经营决策</h1><p>决策会进入市场竞争与企业经营计算，影响你的财务结果和排名。</p></div><div class="decision-state">${sub?badge('已提交','success'):badge('草稿','warning')}<small>${sub?`提交于 ${dateTime(sub.submittedAt)}`:'尚未提交'}</small></div></div>${locked?`<div class="notice-bar"><span class="notice-symbol">✓</span><div><b>本轮决策已锁定</b><small>教师结算前不允许修改。如需修改，请联系教师调整轮次设置。</small></div></div>`:''}<form id="decisionForm" class="decision-form" data-team="${team.id}" data-round="${round.id}"><div class="decision-layout"><div class="decision-main"><section class="panel decision-panel"><div class="decision-section-title"><span class="section-num">01</span><div><h2>产品定价</h2><p>价格影响市场需求、单车收入和品牌定位。</p></div></div><div class="form-grid three">${field('燃油车售价','prices.ice',d.prices.ice,15000,70000,500,'元/辆','市场基准 ¥31,000')}${field('纯电动车售价','prices.ev',d.prices.ev,18000,90000,500,'元/辆','市场基准 ¥39,000')}${field('混合动力售价','prices.hybrid',d.prices.hybrid,16000,80000,500,'元/辆','市场基准 ¥35,000')}</div><div class="form-grid"><label class="form-field"><span>企业经营策略</span><select name="strategy"><option value="balanced" ${d.strategy==='balanced'?'selected':''}>均衡增长 · 平衡投入和利润</option><option value="value" ${d.strategy==='value'?'selected':''}>低价扩张 · 以价格和销量取胜</option><option value="premium" ${d.strategy==='premium'?'selected':''}>高端品牌 · 聚焦品牌溢价</option><option value="innovation" ${d.strategy==='innovation'?'selected':''}>技术领先 · 优先投入产品研发</option></select><small class="field-hint">策略会影响整体产品竞争力。</small></label></div></section><section class="panel decision-panel"><div class="decision-section-title"><span class="section-num">02</span><div><h2>生产与供应链</h2><p>合理安排产量、产能与关键零部件采购。</p></div></div><div class="form-grid three">${field('燃油车计划产量','production.ice',d.production.ice,0,15000,100,'辆')}${field('纯电动车计划产量','production.ev',d.production.ev,0,15000,100,'辆')}${field('混合动力计划产量','production.hybrid',d.production.hybrid,0,10000,100,'辆')}</div><div class="form-grid four">${field('钢材采购','procurement.steel',d.procurement.steel,1,10,1,'等级')}${field('电池采购','procurement.battery',d.procurement.battery,1,10,1,'等级')}${field('芯片采购','procurement.chip',d.procurement.chip,1,10,1,'等级')}${field('零部件采购','procurement.parts',d.procurement.parts,1,10,1,'等级')}</div><div class="form-grid three">${field('产能扩建','capacityExpansion',d.capacityExpansion,0,5000,100,'辆')}${field('外包产能','outsourcing',d.outsourcing,0,3000,100,'辆')}${field('库存目标','inventoryTarget',d.inventoryTarget,0,30,1,'%')}</div></section><section class="panel decision-panel"><div class="decision-section-title"><span class="section-num">03</span><div><h2>市场营销投入</h2><p>营销投入提升产品曝光和市场触达，单位为百万美元。</p></div></div><div class="form-grid four">${field('广告预算','marketing.advertising',d.marketing.advertising,0,25,.5,'百万美元')}${field('品牌推广','marketing.brand',d.marketing.brand,0,25,.5,'百万美元')}${field('销售渠道','marketing.channel',d.marketing.channel,0,25,.5,'百万美元')}${field('促销预算','marketing.promotion',d.marketing.promotion,0,25,.5,'百万美元')}</div></section><section class="panel decision-panel"><div class="decision-section-title"><span class="section-num">04</span><div><h2>研发投入</h2><p>研发积累提升产品竞争力，并形成当期费用。</p></div></div><div class="form-grid three">${field('电池技术','research.battery',d.research.battery,0,20,.5,'百万美元')}${field('发动机研发','research.engine',d.research.engine,0,20,.5,'百万美元')}${field('自动驾驶','research.autonomous',d.research.autonomous,0,20,.5,'百万美元')}${field('产品质量','research.quality',d.research.quality,0,20,.5,'百万美元')}${field('新能源技术','research.newEnergy',d.research.newEnergy,0,20,.5,'百万美元')}</div></section><section class="panel decision-panel"><div class="decision-section-title"><span class="section-num">05</span><div><h2>财务与区域策略</h2><p>融资增加可用资金但带来利息成本，投资影响本轮现金流。</p></div></div><div class="form-grid four">${field('银行贷款','finance.loan',d.finance.loan,0,50,.5,'百万美元')}${field('资本支出','finance.capex',d.finance.capex,0,40,.5,'百万美元')}${field('股权融资','finance.equity',d.finance.equity,0,50,.5,'百万美元')}${field('股息分配','finance.dividend',d.finance.dividend,0,30,.5,'百万美元')}</div><div class="form-grid three">${field('中国区域投入占比','regions.china',d.regions.china,0,100,1,'%')}${field('欧洲区域投入占比','regions.europe',d.regions.europe,0,100,1,'%')}${field('北美区域投入占比','regions.northAmerica',d.regions.northAmerica,0,100,1,'%')}</div></section></div><aside class="decision-aside"><section class="panel decision-guide"><div class="panel-head"><div><h2>本轮市场简报</h2><p>第 ${round.number} 轮关键市场参数</p></div></div><div class="guide-stat"><span>行业需求指数</span><b>${fmt(round.market.demandIndex*100,0)}</b></div><div class="guide-stat"><span>纯电市场增长</span><b class="positive">+${fmt(round.market.evGrowth,1)}%</b></div><div class="guide-stat"><span>原材料指数</span><b>${fmt(100+round.market.materialPriceIndex,0)}</b></div><div class="guide-tip"><b>决策提示</b><p>价格、营销和研发共同影响需求；生产受产能和现有库存限制。请关注团队的现金余额和本轮成本。</p></div></section><section class="panel decision-guide"><div class="panel-head"><div><h2>上轮经营表现</h2><p>${team.name} · 第 ${activeSim().currentRound-1} 轮</p></div></div><div class="mini-kpi"><span>营业收入</span><b>${money(currentResult(team)?.revenue)}</b></div><div class="mini-kpi"><span>净利润</span><b>${money(currentResult(team)?.netProfit)}</b></div><div class="mini-kpi"><span>现金余额</span><b>${money(currentResult(team)?.cash??100)}</b></div></section></aside></div><div class="decision-footer"><div><b>${sub?`已提交 · 版本 ${sub.version}`:'决策尚未提交'}</b><small>保存草稿不会提交给教师。截止时间：${dateTime(round.deadline)}</small></div><div class="heading-actions"><button type="button" class="btn secondary" data-action="validate-decision">检查决策</button><button type="button" class="btn secondary" data-action="save-draft" ${locked?'disabled':''}>保存草稿</button><button type="button" class="btn primary" data-action="submit-decision" ${locked?'disabled':''}>${sub?'更新并重新提交':'提交本轮决策'} ${icon('send')}</button></div></div></form>`;
  }

  function studentResults(){const team=teamBy(ui.teamId)||db.teams[0];const hist=db.results.filter(r=>r.teamId===team.id).sort((a,b)=>a.round-b.round);const latest=hist.at(-1)||{};const rows=hist.slice().reverse().map(r=>`<tr><td>第 ${r.round} 轮</td><td>${money(r.revenue)}</td><td class="${r.netProfit>=0?'positive':'negative'}">${money(r.netProfit)}</td><td>${money(r.productionCost)}</td><td>${money(r.cashFlow)}</td><td>${money(r.cash)}</td><td>${integer(r.inventoryUnits)}</td><td>${fmt(r.score,0)}</td></tr>`);return `<div class="page-heading"><div><div class="eyebrow">财务报表与排行榜</div><h1>财务与排名</h1><p>查看企业各轮财务报表、经营结果和团队排名。</p></div><div class="market-period">${icon('car')}${esc(team.name)}</div></div><div class="metrics-grid compact">${metric('本轮营业收入',money(latest.revenue),'第 '+(latest.round||'—')+' 轮','wallet','blue')}${metric('本轮净利润',money(latest.netProfit),'经营利润','chart',latest.netProfit>=0?'green':'orange')}${metric('生产成本',money(latest.productionCost),'材料、制造与采购','settings','violet')}${metric('期末现金',money(latest.cash??100),'现金流 '+money(latest.cashFlow),'wallet','cyan')}</div>${panel('企业财务报表','金额单位：百万美元；数据由每轮经营决策计算生成',table(['轮次','营业收入','净利润','生产成本','经营现金流','期末现金','库存','综合得分'],rows,'本企业还没有已结算结果'))}${panel('团队排行榜','最近一轮已发布结果',`<div class="leaderboard">${db.teams.map(t=>({t,r:currentResult(t)||{}})).sort((a,b)=>(b.r.score||0)-(a.r.score||0)).map(({t,r},i)=>`<div class="leader-row ${t.id===team.id?'own-team':''}"><span class="rank rank-${i+1}">${i+1}</span><span class="team-avatar" style="--team:${t.color}">${esc(t.name.slice(0,1))}</span><b>${esc(t.name)}</b><div class="leader-score-track"><i style="width:${r.score||0}%"></i></div><strong>${r.score?fmt(r.score,0):'—'}</strong><small>${pct(r.marketShare)}</small></div>`).join('')}`)}`;}

  function marketSectionEditor(selected={}){const current={...DEFAULT_MARKET_SECTIONS,...selected};return `<fieldset class="market-section-editor"><legend>学生端市场分析内容</legend><p>勾选本课程要向学生展示的文字简报模块。</p><div class="market-section-options">${MARKET_MODULES.map(m=>`<label><input type="checkbox" name="market_${m.key}" ${current[m.key]?'checked':''}><span>${m.label}</span></label>`).join('')}</div></fieldset>`;}
  function modalHtml(){
    if(ui.modal==='reset-confirm') return `<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="reset-title"><div class="modal-head"><h2 id="reset-title">重置演示数据</h2><button class="icon-button" data-action="close-modal">×</button></div><p>将清除当前课程修改、学生与团队调整、决策和经营结果，恢复五个团队、二十名学生和六轮演示数据。此操作无法撤销。</p><div class="modal-actions"><button class="btn secondary" data-action="close-modal">取消</button><button class="btn primary" data-action="confirm-reset">确认重置</button></div></section></div>`;
    if(ui.modal==='course') {const c=ui.courseEdit||{};return `<div class="modal-backdrop" data-action="close-modal"><div class="modal large"><div class="modal-head"><div><h2>${c.id?'编辑课程':'创建课程'}</h2><p>设置课程信息和汽车行业模拟场景。</p></div><button class="icon-button" data-action="close-modal">×</button></div><form id="courseForm"><input type="hidden" name="id" value="${escAttr(c.id||'')}"><div class="form-grid two">${textField('课程名称','name',c.name||'','例如：汽车企业经营模拟课程')}${selectField('行业类型','industry',c.industry||'汽车制造',['汽车制造','新能源汽车','智能出行'])}<label class="form-field full-span"><span>课程介绍</span><textarea name="description" rows="2" placeholder="说明课程学习目标与经营重点">${esc(c.description||'')}</textarea></label>${selectField('模拟场景','scenario',c.scenario||'新能源与燃油车双市场',['燃油汽车市场','新能源汽车市场','混合汽车市场','新能源与燃油车双市场'])}${selectField('市场区域','region',c.region||'中国 / 欧洲 / 北美',['中国','欧洲','北美','全球市场','中国 / 欧洲 / 北美'])}${selectField('模拟难度','difficulty',c.difficulty||'进阶',['入门','标准','进阶','挑战'])}${textField('开始日期','startDate',localInputDate(c.startDate||Date.now(),true),'','date')}${textField('结束日期','endDate',localInputDate(c.endDate||Date.now()+86400000*45,true),'','date')}${textField('初始资金（百万美元）','initialCapital',c.initialCapital||100,'团队开局现金','number')}${textField('初始工厂产能（辆）','initialCapacity',c.initialCapacity||10000,'每轮可用基础产能','number')}${textField('初始市场份额（%）','initialMarketShare',c.initialMarketShare||20,'用于计算初始需求','number')}${textField('产品数量','productCount',c.productCount||3,'产品细分数量','number')}${textField('团队数量','teamCount',c.teamCount||db.teams.length,'模拟企业数量','number')}${textField('每组人数','membersPerTeam',c.membersPerTeam||4,'建议每组 3–6 人','number')}</div>${marketSectionEditor(c.marketSections)}<div class="modal-actions"><button type="button" class="btn secondary" data-action="close-modal">取消</button><button class="btn primary" type="submit">保存课程</button></div></form></div></div>`;}
    if(ui.modal==='round') {const r=ui.roundEdit||{};return `<div class="modal-backdrop" data-action="close-modal"><div class="modal large"><div class="modal-head"><div><h2>${r.id?'编辑轮次设置':'添加模拟轮次'}</h2><p>设置轮次时间、提交规则与市场环境参数。</p></div><button class="icon-button" data-action="close-modal">×</button></div><form id="roundForm"><input type="hidden" name="id" value="${escAttr(r.id||'')}"><div class="form-grid two">${textField('轮次名称','name',r.name||`第 ${db.rounds.length+1} 轮`)}${textField('轮次序号','number',r.number||db.rounds.length+1,'用于模拟顺序','number')}${textField('开始时间','startAt',localInputDate(r.startAt||Date.now()),'','datetime-local')}${textField('截止时间','deadline',localInputDate(r.deadline||Date.now()+86400000*3),'','datetime-local')}${textField('行业需求指数','demandIndex',r.market?.demandIndex||1.1,'基准值 1.0','number')}${textField('纯电市场增长率（%）','evGrowth',r.market?.evGrowth??12,'','number')}${textField('燃油市场增长率（%）','iceGrowth',r.market?.iceGrowth??0,'','number')}${textField('原材料价格变化（%）','materialPriceIndex',r.market?.materialPriceIndex??0,'','number')}${textField('行业竞争需求量','competitorDemand',r.market?.competitorDemand||150000,'市场竞争基数','number')}${textField('允许修改决策','allowEdit',r.allowEdit??true,'学生提交后是否可修改','checkbox')}${textField('允许提前提交','allowEarlySubmit',r.allowEarlySubmit??true,'','checkbox')}${textField('自动进入下一轮','autoAdvance',r.autoAdvance??false,'','checkbox')}</div><div class="modal-actions"><button type="button" class="btn secondary" data-action="close-modal">取消</button><button class="btn primary" type="submit">保存轮次设置</button></div></form></div></div>`;}
    if(ui.modal==='student') {const s=ui.studentEdit||{};return `<div class="modal-backdrop" data-action="close-modal"><div class="modal"><div class="modal-head"><div><h2>${s.id?'编辑学生':'添加学生'}</h2><p>维护学生信息和所属团队。</p></div><button class="icon-button" data-action="close-modal">×</button></div><form id="studentForm"><input type="hidden" name="id" value="${s.id||''}"><div class="form-grid">${textField('学生姓名','name',s.name||'')}${textField('邮箱','email',s.email||'','student@bizsim.edu','email')}${selectField('所属团队','teamId',s.teamId||db.teams[0]?.id,db.teams.map(t=>[t.id,t.name]))}</div><div class="modal-actions"><button type="button" class="btn secondary" data-action="close-modal">取消</button><button class="btn primary" type="submit">保存学生</button></div></form></div></div>`;}
    if(ui.modal==='team')return `<div class="modal-backdrop" data-action="close-modal"><div class="modal"><div class="modal-head"><div><h2>创建模拟团队</h2><p>新增一家参与市场竞争的模拟企业。</p></div><button class="icon-button" data-action="close-modal">×</button></div><form id="teamForm"><div class="form-grid">${textField('团队名称','name','','例如：远航汽车')}${selectField('策略定位','strategy','均衡增长',STRATEGIES)}</div><div class="modal-actions"><button type="button" class="btn secondary" data-action="close-modal">取消</button><button class="btn primary" type="submit">创建团队</button></div></form></div></div>`;
    if(ui.modal==='detail') {const t=teamBy(ui.detailId);const r=currentResult(t)||{};return `<div class="modal-backdrop" data-action="close-modal"><div class="modal"><div class="modal-head"><div><h2>${esc(t.name)} · 经营详情</h2><p>${esc(t.strategy)} · 当前模拟轮次</p></div><button class="icon-button" data-action="close-modal">×</button></div><div class="detail-kpis">${[['现金余额',money(r.cash??100)],['营业收入',money(r.revenue)],['净利润',money(r.netProfit)],['市场份额',pct(r.marketShare)],['总销量',integer(r.totalSales)],['企业得分',fmt(r.score,0)]].map(([a,b])=>`<div><small>${a}</small><b>${b}</b></div>`).join('')}</div><h3 class="modal-subtitle">团队成员</h3><div class="member-list">${db.students.filter(s=>s.teamId===t.id).map(s=>`<div><span class="member-avatar">${esc(s.name.slice(-1))}</span><b>${esc(s.name)}</b><small>${esc(s.studentNo)}</small></div>`).join('')}</div><div class="modal-actions"><button class="btn secondary" data-action="close-modal">关闭</button></div></div></div>`;}
    if(ui.modal==='submission') {const team=teamBy(ui.detailId),round=currentRound(),d=BizSimEngine.mergeDecision(db.decisions[`${team.id}_${round.id}`]||{});return `<div class="modal-backdrop" data-action="close-modal"><div class="modal"><div class="modal-head"><div><h2>${esc(team.name)} · 第 ${round.number} 轮决策</h2><p>已提交于 ${dateTime(subFor(team.id,round.id)?.submittedAt)}</p></div><button class="icon-button" data-action="close-modal">×</button></div><div class="submission-detail"><div><small>定价</small><b>燃油 ${integer(d.prices.ice)} 元 · 纯电 ${integer(d.prices.ev)} 元 · 混合 ${integer(d.prices.hybrid)} 元</b></div><div><small>生产计划</small><b>燃油 ${integer(d.production.ice)} 辆 · 纯电 ${integer(d.production.ev)} 辆 · 混合 ${integer(d.production.hybrid)} 辆</b></div><div><small>营销总投入</small><b>${money(Object.values(d.marketing).reduce((a,v)=>a+v,0))}</b></div><div><small>研发总投入</small><b>${money(Object.values(d.research).reduce((a,v)=>a+v,0))}</b></div><div><small>融资</small><b>贷款 ${money(d.finance.loan)} · 股权 ${money(d.finance.equity)}</b></div><div><small>经营策略</small><b>${esc(d.strategy)}</b></div></div><div class="modal-actions"><button class="btn secondary" data-action="close-modal">关闭</button></div></div></div>`;}
    return '';
  }
  function textField(label,name,value='',placeholder='',type='text'){if(type==='checkbox')return `<label class="check-field"><input type="checkbox" name="${name}" ${value?'checked':''}><span>${esc(label)}</span><small>${esc(placeholder)}</small></label>`;return `<label class="form-field"><span>${esc(label)}</span><input type="${type}" name="${name}" value="${escAttr(value)}" placeholder="${escAttr(placeholder)}" ${type==='number'?`step="${['number','initialCapacity','productCount','teamCount','membersPerTeam','competitorDemand'].includes(name)?'1':'any'}" ${['evGrowth','iceGrowth','materialPriceIndex'].includes(name)?'':'min="0"'}`:''} required></label>`;}
  function selectField(label,name,value,options){return `<label class="form-field"><span>${esc(label)}</span><select name="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${escAttr(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`;}

  function render(){
    if(route==='/'){ $('#app').innerHTML=portalChooser(); return; }
    if(route!=='/teacher'&&route!=='/student'){ window.location.replace('/'); return; }
    if(ui.role==='teacher'&&sessionStorage.getItem('bizsim-teacher-session')!==db.teachers[0]?.id){ $('#app').innerHTML=loginPage(); return; }
    if(ui.role==='student'&&!db.students.some(s=>s.id===sessionStorage.getItem('bizsim-student-session'))){ $('#app').innerHTML=loginPage(); return; }
    const pages={overview:overviewPage,courses:coursesPage,rounds:roundsPage,teams:teamsPage,submissions:submissionsPage,results:resultsPage,'student-home':studentHome,market:marketPage,decisions:decisionsPage,'student-results':studentResults};
    const valid=ui.role==='teacher'?['overview','courses','rounds','teams','submissions','results']:['student-home','market','decisions','student-results'];if(!valid.includes(ui.page))ui.page=valid[0];
    $('#app').innerHTML=shell((pages[ui.page]||overviewPage)());
  }
  function log(message,type='activity'){db.events.unshift({id:uid('event'),type,message,at:new Date().toISOString()});db.events=db.events.slice(0,30);}
  function formObj(form){return Object.fromEntries(new FormData(form).entries());}
  function setDecisionValue(obj,path,value){const parts=path.split('.');let cur=obj;while(parts.length>1)cur=cur[parts.shift()];cur[parts[0]]=Number(value);}
  function collectDecision(form){const d=BizSimEngine.mergeDecision({});for(const input of $$('input[name]',form)){const path=input.name;if(path.includes('.'))setDecisionValue(d,path,input.value);else d[path]=Number(input.value);}const strategy=$('select[name="strategy"]',form);if(strategy)d.strategy=strategy.value;return d;}
  function validateDecision(d,teamId){const errors=[];const total=d.regions.china+d.regions.europe+d.regions.northAmerica;if(Math.abs(total-100)>0.01)errors.push('区域投入占比合计必须为 100%（当前 '+fmt(total,1)+'%）。');if(d.finance.dividend>100)errors.push('股息金额超出建议上限。');if(d.production.ice+d.production.ev+d.production.hybrid<=0)errors.push('请至少设置一种车型的生产数量。');const prev=currentResult(teamBy(teamId));if(prev?.cash!==undefined&&prev.cash<0&&!d.finance.loan&&!d.finance.equity)errors.push('企业现金余额为负，建议配置融资。');return errors;}
  function saveDecision(mode){const form=$('#decisionForm');if(!form)return;const d=collectDecision(form);const teamId=form.dataset.team,roundId=form.dataset.round;const errors=validateDecision(d,teamId);const round=currentRound();if(mode==='submit'&&!round.allowEarlySubmit&&Date.now()<new Date(round.startAt).getTime()){toast('本轮尚未开始，教师未允许提前提交。');return;}if(mode==='submit'&&Date.now()>new Date(round.deadline).getTime()){toast('本轮提交截止时间已过。');return;}if(mode==='validate'){toast(errors.length?errors.join(' '):'决策检查通过，可以保存或提交。');return;}if(errors.length){toast(errors[0]);return;}db.decisions[`${teamId}_${roundId}`]=d;if(mode==='submit'){const existing=subFor(teamId,roundId);if(existing&&!currentRound().allowEdit){toast('本轮决策已锁定，不能修改。');return;}if(existing){existing.version+=1;existing.submittedAt=new Date().toISOString();}else db.submissions.push({id:uid('submission'),teamId,roundId,decisionId:`${teamId}_${roundId}`,status:'已提交',submittedAt:new Date().toISOString(),version:1});log(`${teamBy(teamId).name} 已提交第 ${currentRound().number} 轮经营决策`,'submission');toast(existing?'决策已更新并重新提交。':'经营决策已提交给教师。');}else{log(`${teamBy(teamId).name} 保存了第 ${currentRound().number} 轮决策草稿`,'draft');toast('决策草稿已保存。');}save();render();}
  function executeRound(){const round=currentRound();if(!round){toast('当前没有进行中的轮次。');return;}const missing=db.teams.filter(t=>!subFor(t.id,round.id));if(missing.length){const go=confirm(`${missing.length} 支团队尚未提交。继续结算时将使用其已保存草稿或默认决策。是否继续？`);if(!go)return;}const decisions={};db.teams.forEach(t=>{decisions[t.id]=db.decisions[`${t.id}_${round.id}`]||BizSimEngine.defaults;});const prior={};db.teams.forEach(t=>{const prev=db.results.filter(r=>r.teamId===t.id).sort((a,b)=>b.round-a.round)[0];if(prev)prior[t.id]={cash:prev.cash,debt:prev.debt,inventory:prev.inventory,marketShare:prev.marketShare/100,cumulativeScore:prev.cumulativeScore};else prior[t.id]={cash:db.courses[0].initialCapital,debt:0,inventory:{ice:1200,ev:900,hybrid:400},marketShare:db.courses[0].initialMarketShare/100,cumulativeScore:0};});const resolved=BizSimEngine.resolveRound(db.teams,decisions,{...round.market,round:round.number},prior,{initialCapital:db.courses[0].initialCapital,initialCapacity:db.courses[0].initialCapacity,initialMarketShare:db.courses[0].initialMarketShare/100});db.results.push(...resolved.results);resolved.results.forEach(r=>db.financialStatements.push({id:uid('financial'),teamId:r.teamId,round:round.number,revenue:r.revenue,netProfit:r.netProfit,productionCost:r.productionCost,cashFlow:r.cashFlow,cash:r.cash,debt:r.debt,inventory:r.inventory,calculatedAt:resolved.calculatedAt}));db.leaderboard=resolved.results.map(r=>({teamId:r.teamId,round:r.round,rank:r.rank,score:r.score,marketShare:r.marketShare}));round.status='已结束';round.resolvedAt=resolved.calculatedAt;round.resultSnapshot={market:resolved.marketSnapshot,inputs:resolved.inputs};if(round.number<db.rounds.length){const next=db.rounds.find(r=>r.number===round.number+1);activeSim().currentRound=next.number;if(round.autoAdvance){next.status='进行中';log(`第 ${round.number} 轮已完成结算，第 ${next.number} 轮现已开放`,'result');}else{log(`第 ${round.number} 轮已结算，请教师手动开启第 ${next.number} 轮`,'result');}}else{activeSim().status='已完成';log(`第 ${round.number} 轮已完成，模拟全部结束`,'result');}save();ui.page='results';toast(`第 ${round.number} 轮计算完成，结果已生成。`);render();}
  function resetSimulation(){db=makeSeed();save();ui.modal='';ui.resultsRound=null;ui.courseEdit=null;ui.roundEdit=null;ui.studentEdit=null;ui.page=ui.role==='teacher'?'overview':'student-home';toast('演示模拟已重置。');}
  function download(name,rows){const blob=new Blob(['\ufeff'+rows.map(row=>row.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}

  document.addEventListener('click',e=>{
    const page=e.target.closest('[data-page]');if(page){ui.page=page.dataset.page;ui.notice='';render();return;}
    const btn=e.target.closest('[data-action]');if(!btn)return;const a=btn.dataset.action,id=btn.dataset.id;
    if(a==='close-modal'){if(btn.classList.contains('modal-backdrop')&&e.target!==btn)return;ui.modal='';render();}
    else if(a==='new-course'){ui.courseEdit=null;ui.modal='course';render();}
    else if(a==='edit-course'){ui.courseEdit={...db.courses.find(c=>c.id===id)};ui.modal='course';render();}
    else if(a==='copy-course'){const c={...db.courses.find(c=>c.id===id),id:uid('course'),name:db.courses.find(c=>c.id===id).name+'（副本）',status:'未开始'};db.courses.push(c);save();toast('课程副本已创建。');}
    else if(a==='delete-course'){if(db.courses.length===1){toast('至少保留一个课程。');return;}if(confirm('确定删除此课程吗？课程关联的模拟记录仍保留。')){db.courses=db.courses.filter(c=>c.id!==id);save();toast('课程已删除。');}}
    else if(a==='new-round'){ui.roundEdit=null;ui.modal='round';render();}
    else if(a==='edit-round'){ui.roundEdit=structuredClone(db.rounds.find(r=>r.id===id));ui.modal='round';render();}
    else if(a==='delete-round'){if(confirm('删除此未开始轮次？')){db.rounds=db.rounds.filter(r=>r.id!==id);db.rounds.forEach((r,i)=>r.number=i+1);save();toast('轮次已删除并重新排序。');}}
    else if(a==='start-round'){const r=db.rounds.find(r=>r.id===id);if(db.rounds.some(x=>x.status==='进行中')){toast('请先结束当前进行中的轮次。');return;}r.status='进行中';activeSim().currentRound=r.number;save();log(`${r.name}已由教师开启`,'round');toast(`${r.name}已开始。`);}
    else if(a==='finish-round'){executeRound();}
    else if(a==='view-round'){ui.resultsRound=db.rounds.find(r=>r.id===id)?.number;ui.page='results';render();}
    else if(a==='reset-simulation'||a==='reset'){ui.modal='reset-confirm';render();}
    else if(a==='confirm-reset'){resetSimulation();}
    else if(a==='new-student'){ui.studentEdit=null;ui.modal='student';render();}
    else if(a==='edit-student'){ui.studentEdit={...db.students.find(s=>s.id===id)};ui.modal='student';render();}
    else if(a==='new-team'){ui.modal='team';render();}
    else if(a==='team-detail'){ui.detailId=id;ui.modal='detail';render();}
    else if(a==='view-submission'){ui.detailId=id;ui.modal='submission';render();}
    else if(a==='save-draft'){saveDecision('draft');}
    else if(a==='validate-decision'){saveDecision('validate');}
    else if(a==='submit-decision'){saveDecision('submit');}
    else if(a==='logout'){sessionStorage.removeItem(ui.role==='teacher'?'bizsim-teacher-session':'bizsim-student-session');ui.loginError='';ui.studentId=null;ui.teamId=null;render();}
    else if(a==='export-submissions'){download('BizSim_决策提交记录.csv',[['团队','状态','提交时间','轮次'],...db.teams.map(t=>{const s=subFor(t.id,currentRound()?.id);return[t.name,s?.status||'待提交',s?.submittedAt||'',currentRound()?.number||''];})]);}
    else if(a==='export-results'){const n=selectedResultsRound();if(!n){toast('暂无可导出的经营结果。');return;}download(`BizSim_第${n}轮经营结果.csv`,[['轮次','排名','团队','营业收入（百万美元）','净利润（百万美元）','市场份额（%）','销售数量','生产成本（百万美元）','期末库存','现金余额（百万美元）','综合得分'],...db.teams.map(t=>({t,r:resultFor(t.id,n)})).map(({t,r})=>r?[n,r.rank,r.teamName,r.revenue,r.netProfit,r.marketShare,r.totalSales,r.productionCost,r.inventoryUnits,r.cash,r.score]:[n,'',t.name,'','','','','','','',''])]);}
  });
  document.addEventListener('change',e=>{
    if(e.target.id==='resultsRound'){ui.resultsRound=Number(e.target.value);render();return;}
  });
  document.addEventListener('input',e=>{if(typeof e.target.setCustomValidity==='function')e.target.setCustomValidity('');});
  document.addEventListener('submit',e=>{
    e.preventDefault();const form=e.target;
    const formId=form.getAttribute('id');
    if(['courseForm','roundForm'].includes(formId)){
      const start=form.elements.namedItem(formId==='courseForm'?'startDate':'startAt');
      const end=form.elements.namedItem(formId==='courseForm'?'endDate':'deadline');
      end.setCustomValidity(new Date(end.value)<=new Date(start.value)?'结束或截止时间必须晚于开始时间。':'');
      if(formId==='roundForm'){
        const o=formObj(form), old=db.rounds.find(r=>r.id===o.id);
        const expected=old?old.number:db.rounds.length+1;
        form.elements.namedItem('number').setCustomValidity(Number(o.number)!==expected?'轮次序号应为 '+expected+'，避免改变已有关联记录。':'');
      }
      if(!form.reportValidity())return;
    }
    if(formId==='loginForm'){const o=formObj(form);if(ui.role==='teacher'){const teacher=db.teachers[0];if(o.email!==teacher.email||o.password!=='teacher123'){ui.loginError='教师邮箱或演示密码不正确。';render();return;}sessionStorage.setItem('bizsim-teacher-session',teacher.id);ui.page='overview';ui.loginError='';}else{const student=db.students.find(st=>st.email===o.email);if(!student||o.password!=='student123'){ui.loginError='学生账号或演示密码不正确。';render();return;}sessionStorage.setItem('bizsim-student-session',student.id);ui.studentId=student.id;ui.teamId=student.teamId;ui.page='student-home';ui.loginError='';}render();}
    else if(formId==='courseForm'){const o=formObj(form);const found=db.courses.find(c=>c.id===o.id);const marketSections=Object.fromEntries(MARKET_MODULES.map(m=>[m.key,!!form.elements['market_'+m.key]?.checked]));MARKET_MODULES.forEach(m=>delete o['market_'+m.key]);const value={...(found||{}),...o,marketSections,name:o.name.trim(),teamCount:Number(o.teamCount),membersPerTeam:Number(o.membersPerTeam),initialCapital:Number(o.initialCapital),initialCapacity:Number(o.initialCapacity),initialMarketShare:Number(o.initialMarketShare),productCount:Number(o.productCount),startDate:new Date(o.startDate).toISOString(),endDate:new Date(o.endDate).toISOString(),status:found?.status||'未开始'};if(found)Object.assign(found,value);else{db.courses.push({...value,id:uid('course')});log(`已创建课程：${value.name}`,'course');}save();ui.modal='';toast(found?'课程设置已更新。':'课程已创建。');}
    else if(formId==='roundForm'){const o=formObj(form);const found=db.rounds.find(r=>r.id===o.id);const number=Number(o.number);const value={...(found||{}),id:found?.id||uid('round'),simulationId:activeSim().id,number,name:o.name||`第 ${number} 轮`,status:found?.status||'未开始',startAt:new Date(o.startAt).toISOString(),deadline:new Date(o.deadline).toISOString(),allowEdit:form.elements.allowEdit.checked,allowEarlySubmit:form.elements.allowEarlySubmit.checked,autoAdvance:form.elements.autoAdvance.checked,publishResults:true,decisionItems:found?.decisionItems||['定价','生产计划','市场营销','研发投入','供应链采购','财务管理'],market:{round:number,demandIndex:Number(o.demandIndex),evGrowth:Number(o.evGrowth),iceGrowth:Number(o.iceGrowth),materialPriceIndex:Number(o.materialPriceIndex),competitorDemand:Number(o.competitorDemand),demand:found?.market?.demand||{ice:52000,ev:46000,hybrid:21000},regions:found?.market?.regions||{china:.49,europe:.29,northAmerica:.22}}};if(found)Object.assign(found,value);else db.rounds.push(value);db.rounds.sort((a,b)=>a.number-b.number);db.rounds.forEach((r,i)=>{r.number=i+1;r.market.round=r.number;});save();ui.modal='';toast(found?'轮次设置已更新。':'模拟轮次已添加。');}
    else if(formId==='studentForm'){const o=formObj(form);if(o.id){const student=db.students.find(s=>s.id===o.id);Object.assign(student,o);db.teamMembers=db.teamMembers.filter(m=>m.studentId!==student.id);db.teamMembers.push({teamId:student.teamId,studentId:student.id,role:'成员'});}else{const s={...o,id:uid('student'),studentNo:`BS${Date.now().toString().slice(-7)}`};db.students.push(s);db.teamMembers.push({teamId:s.teamId,studentId:s.id,role:'成员'});}save();ui.modal='';toast('学生信息已保存。');}
    else if(formId==='teamForm'){const o=formObj(form);const t={id:uid('team'),name:o.name.trim(),strategy:o.strategy,color:['#2563eb','#8b5cf6','#0891b2','#ea580c','#16a34a'][db.teams.length%5],createdAt:new Date().toISOString()};db.teams.push(t);db.courses[0].teamCount=db.teams.length;save();ui.modal='';toast('模拟团队已创建。');}
    render();
  });
  render();
})();
